#!/usr/bin/expect -f
#
# Witness test for: "ssh -p 2222 root@localhost with password password123
# drops into a shell."
#
# Exits 0 on success (proves we got a shell and ran a command in it),
# non-zero on any failure. Designed to be re-runnable: it connects, logs
# in, runs a sentinel command, and disconnects.

set timeout 30

# Don't add host key to known_hosts; accept it automatically to avoid
# getting stuck on the host-key prompt.
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost

expect {
    -re "(?i)password:" {
        send "password123\r"
    }
    -re "(?i)permission denied" {
        send_user "\nFAIL: got 'permission denied' before entering password\n"
        exit 1
    }
    timeout {
        send_user "\nFAIL: timed out waiting for password prompt\n"
        exit 1
    }
    eof {
        send_user "\nFAIL: connection closed before password prompt\n"
        exit 1
    }
}

# Wait for the remote shell prompt. Use a loose match so we don't depend
# on the exact prompt string.
expect {
    -re "(?i)password:" {
        send_user "\nFAIL: password rejected (got a second password prompt)\n"
        exit 1
    }
    -re {\$ $} {
        # plain $ prompt
    }
    -re {# $} {
        # root # prompt
    }
    -re {localhost:~#} {
    }
    -re {:~#} {
    }
    -re {[#\$] $} {
    }
    timeout {
        send_user "\nFAIL: timed out waiting for shell prompt after login\n"
        exit 1
    }
    eof {
        send_user "\nFAIL: connection closed after password (auth failed?)\n"
        exit 1
    }
}

# Run a sentinel command to prove we really have an interactive shell.
send "echo SSH_LOGIN_OK_\$\$\r"

expect {
    -re {SSH_LOGIN_OK_[0-9]+} {
        send_user "\nPASS: logged in and executed a command in the remote shell\n"
        # Clean up: exit the remote shell.
        send "exit\r"
        expect eof
        exit 0
    }
    timeout {
        send_user "\nFAIL: timed out waiting for sentinel command output\n"
        exit 1
    }
    eof {
        send_user "\nFAIL: connection closed before sentinel output\n"
        exit 1
    }
}

#!/usr/bin/expect -f
#
# Boot the Alpine ISO in QEMU and configure an SSH server over the serial
# console. After configuration completes, this script detaches so that
# qemu keeps running in the background (via nohup/disown wrapper) -- here
# we just leave the spawned qemu alive; the parent shell disowns it.
#
# Configuration performed as root on the serial console:
#   1. Log in as root (no password).
#   2. Set root password to password123.
#   3. Enable root login + password auth in sshd.
#   4. Start the sshd service.
#
# After "SSH_SETUP_COMPLETE" is printed, we expect the sentinel marker,
# then we exit expect WITHOUT killing qemu (by closing our side; the
# nohup wrapper keeps qemu alive).

set timeout 180

# Spawn qemu. Output goes to our stdout so the wrapper log captures boot.
spawn qemu-system-x86_64 \
    -m 512 \
    -cdrom /app/alpine.iso \
    -netdev user,id=n0,hostfwd=tcp::2222-:22 \
    -device e1000,netdev=n0 \
    -nographic

# ---- Wait for the login prompt -------------------------------------------
expect {
    -re "login: $" { }
    timeout {
        send_user "\nSETUP-FAIL: timed out waiting for login prompt\n"
        exit 1
    }
    eof {
        send_user "\nSETUP-FAIL: qemu exited before login prompt\n"
        exit 1
    }
}

# ---- Log in as root (no password) ----------------------------------------
send "root\r"

# After login, expect a root shell prompt (#).
expect {
    -re {[#] $} { }
    -re {localhost:~#} { }
    -re {:~#} { }
    timeout {
        send_user "\nSETUP-FAIL: timed out waiting for root shell after login\n"
        exit 1
    }
}

# Stabilize: send a newline and resync on a known sentinel.
send "echo READY_\$\$\r"
expect {
    -re "READY_[0-9]+" { }
    timeout {
        send_user "\nSETUP-FAIL: could not sync shell (READY marker)\n"
        exit 1
    }
}

# ---- Set root password to password123 ------------------------------------
# passwd reads the new password twice.
send "passwd root\r"
expect {
    -re "(?i)new password" { }
    -re "(?i)password:" { }
    timeout {
        send_user "\nSETUP-FAIL: passwd did not prompt\n"
        exit 1
    }
}
send "password123\r"
expect {
    -re "(?i)retype" { }
    -re "(?i)again" { }
    -re "(?i)new password" { }
    -re "(?i)password:" { }
    timeout {
        send_user "\nSETUP-FAIL: passwd second prompt missing\n"
        exit 1
    }
}
send "password123\r"
expect {
    -re {passwd: (the password was|password (updated|changed)|updated successfully)} { }
    -re {password (for .* )?(has been |is )?changed} { }
    -re {[#] $} { }
    timeout {
        send_user "\nSETUP-FAIL: passwd did not complete\n"
        exit 1
    }
}

# Resync.
send "echo PWSET_\$\$\r"
expect {
    -re "PWSET_[0-9]+" { }
    timeout {
        send_user "\nSETUP-FAIL: shell not responsive after passwd\n"
        exit 1
    }
}

# ---- Configure sshd to permit root login + password auth -----------------
# /etc/ssh/sshd_config exists in the live rootfs. Ensure the relevant
# directives are set. We rewrite the config with explicit values to be
# safe (it's a live ISO rootfs, not persistent).
send "printf 'PermitRootLogin yes\\nPasswordAuthentication yes\\n' > /etc/ssh/sshd_config\r"
expect {
    -re {[#] $} { }
    timeout { }
}

# Generate host keys if missing (setup-sshd / ssh-keygen -A).
send "ssh-keygen -A >/dev/null 2>&1; echo KEYGEN_DONE_\$\$\r"
expect {
    -re "KEYGEN_DONE_[0-9]+" { }
    timeout {
        send_user "\nSETUP-FAIL: ssh-keygen -A did not finish\n"
        exit 1
    }
}

# Start sshd. Prefer the OpenRC service, fall back to running sshd directly.
send "rc-service sshd start 2>/dev/null; rc-service ssh start 2>/dev/null; /usr/sbin/sshd; echo SSHD_STARTED_\$\$\r"
expect {
    -re "SSHD_STARTED_[0-9]+" { }
    timeout {
        send_user "\nSETUP-FAIL: sshd start did not finish\n"
        exit 1
    }
}

# Verify sshd is listening on port 22.
send "netstat -ltn 2>/dev/null | grep ':22 ' || ss -ltn 2>/dev/null | grep ':22 '; echo LISTEN_CHECK_\$\$\r"
expect {
    -re "LISTEN_CHECK_[0-9]+" { }
    timeout {
        send_user "\nSETUP-FAIL: listen check did not finish\n"
        exit 1
    }
}

send_user "\nSSH_SETUP_COMPLETE\n"
# Exit expect. The wrapper (nohup/disown) keeps qemu alive.
# We intentionally do NOT send a shutdown; we want the VM to stay up.
exit 0
